export function exchangeStep(a,b,forward=.2,reverse=.1){if(![a,b,forward,reverse].every(Number.isFinite)||a<0||b<0||forward<0||reverse<0||forward>1||reverse>1)throw Error('Invalid exchange');const f=a*forward,r=b*reverse;return {a:a-f+r,b:b+f-r,forward:f,reverse:r};}
export const equilibriumTasks={reverse:[{id:'dehydrate',title:'Reverse the observation',prompt:'Heating blue hydrated copper sulfate forms white anhydrous material and water. Predict what adding water to the anhydrous material can do.',fields:[['observation','Observation',[['blue','Blue hydrated material returns'],['white','Always stays white'],['metal','Copper metal forms']],'blue'],['energy','Hydration relative to endothermic dehydration',[['out','Exothermic'],['in','Endothermic'],['none','No energy transfer']],'out']]},{id:'energy',title:'Match the energy account',prompt:'The forward change releases40 kJ for the stated quantities and states. Predict its exact reverse.',fields:[['reverse','Reverse change',[['absorb','Absorbs40 kJ'],['release','Releases40 kJ'],['double','Absorbs80 kJ']],'absorb']]},{id:'symbol',title:'Interpret reversibility',prompt:'A ⇌ B has been written. Has equilibrium necessarily already been reached?',fields:[['claim','Conclusion',[['no','No: equal rates and closed conditions needed'],['yes','Yes: the symbol proves equilibrium'],['equal','Yes: equal amounts are compulsory']],'no']]}],dynamic:[{id:'balance',title:'Equal rates, unequal amounts',prompt:'Illustrative closed A ⇌ B model:20 A particles and40 B particles. Each step converts20% of A forward and10% of B reverse. Run the model steps and classify the state.',fields:[['state','State',[['equilibrium','Dynamic equilibrium'],['stopped','Reaction stopped'],['unequal','Not equilibrium because amounts differ']],'equilibrium'],['amount','Macroscopic amounts',[['constant','Constant'],['equal','Must be equal'],['vanish','Must vanish']],'constant']]},{id:'approach',title:'Approach equilibrium',prompt:'Start the same closed model with60 A and0 B. Run steps. Initially forward change exceeds reverse; the exchanges approach equality.',fields:[['initial','Initial reverse rate',[['zero','Zero'],['largest','Larger than forward'],['equal','Always equal']],'zero'],['later','Later fixed-condition behaviour',[['equalrates','Rates approach equality'],['stop','Both rates must become zero'],['equalamount','Amounts must become equal']],'equalrates']]},{id:'escape',title:'Open the boundary',prompt:'Suppose product gas is allowed to leave the reversible system continuously.',fields:[['condition','Equilibrium requirement',[['closed','Retain reactants and products'],['open','Escape guarantees equilibrium'],['freeze','Freeze every particle']],'closed']]}],shift:[{id:'concentration',title:'Replace removed product',prompt:'A+B ⇌ C is at equilibrium. Some C is removed while other conditions stay fixed.',fields:[['direction','Favoured response',[['right','Toward C'],['left','Toward A+B'],['none','No response possible']],'right']]},{id:'temperature',title:'Heat an exothermic forward reaction',prompt:'N₂+3H₂ ⇌2NH₃ releases energy in the forward direction. Temperature increases.',fields:[['direction','Equilibrium shift',[['left','Toward reactants'],['right','Toward ammonia'],['none','Always unchanged']],'left'],['why','Reason',[['endo','Favours endothermic direction'],['faster','Faster always means more product'],['mass','Nitrogen mass doubles']],'endo']]},{id:'pressure',title:'Compress the gases',prompt:'At fixed temperature compress N₂(g)+3H₂(g) ⇌2NH₃(g).',fields:[['direction','Equilibrium shift',[['right','Toward ammonia'],['left','Toward reactants'],['none','No change because atom counts equal']],'right'],['why','Gas molecule count',[['fewer','Four molecules to two'],['more','Two molecules to four'],['atoms','Only atom totals matter']],'fewer']]}]};
export const equilibriumCorrect=(t,a)=>t.fields.every(([id,,,key])=>a[id]===key);
